-- ==========================================
-- Manufacturing Dataset
-- Generated Automatically
-- ==========================================

-- ==========================================
-- SCHEMA
-- ==========================================

DROP DATABASE IF EXISTS manufacturing_test;

CREATE DATABASE manufacturing_test
CHARACTER SET utf8mb4
COLLATE utf8mb4_unicode_ci;

USE manufacturing_test;

-- ==========================================================
-- EMPLOYEE
-- ==========================================================

CREATE TABLE employee
(
    employee_no     VARCHAR(10) PRIMARY KEY,
    full_name       VARCHAR(100) NOT NULL
);

-- ==========================================================
-- MACHINE
-- ==========================================================

CREATE TABLE machine
(
    machine_code        VARCHAR(10) PRIMARY KEY,
    machine_name        VARCHAR(100) NOT NULL,
    production_line     VARCHAR(50) NOT NULL
);

-- ==========================================================
-- PRODUCT
-- ==========================================================

CREATE TABLE product
(
    product_code        VARCHAR(20) PRIMARY KEY,
    product_name        VARCHAR(150) NOT NULL,
    category            VARCHAR(50) NOT NULL,
    target_min          INT NOT NULL,
    target_max          INT NOT NULL
);

-- ==========================================================
-- WORK ORDER
-- ==========================================================

CREATE TABLE work_order
(
    wo_number           VARCHAR(20) PRIMARY KEY,

    product_code        VARCHAR(20) NOT NULL,

    machine_code        VARCHAR(10) NOT NULL,

    employee_no         VARCHAR(10) NOT NULL,

    shift               VARCHAR(20) NOT NULL,

    target_qty          INT NOT NULL,

    plan_start          DATETIME NOT NULL,

    plan_finish         DATETIME NOT NULL,

    status              VARCHAR(20) NOT NULL,

    CONSTRAINT fk_wo_product
        FOREIGN KEY(product_code)
        REFERENCES product(product_code),

    CONSTRAINT fk_wo_machine
        FOREIGN KEY(machine_code)
        REFERENCES machine(machine_code),

    CONSTRAINT fk_wo_employee
        FOREIGN KEY(employee_no)
        REFERENCES employee(employee_no)
);

-- ==========================================================
-- PRODUCTION RESULT
-- ==========================================================

CREATE TABLE production_result
(
    id                  INT AUTO_INCREMENT PRIMARY KEY,

    wo_number           VARCHAR(20) NOT NULL,

    actual_start        DATETIME NOT NULL,

    actual_finish       DATETIME NOT NULL,

    runtime_minutes     INT NOT NULL,

    good_qty            INT NOT NULL,

    reject_qty          INT NOT NULL,

    achievement         DECIMAL(8,2) NOT NULL,

    CONSTRAINT fk_prod_wo
        FOREIGN KEY(wo_number)
        REFERENCES work_order(wo_number)
);

-- ==========================================================
-- DOWNTIME
-- ==========================================================

CREATE TABLE downtime
(
    id                  INT AUTO_INCREMENT PRIMARY KEY,

    wo_number           VARCHAR(20) NOT NULL,

    downtime_reason     VARCHAR(100) NOT NULL,

    start_time          DATETIME NOT NULL,

    end_time            DATETIME NOT NULL,

    duration_minutes    INT NOT NULL,

    CONSTRAINT fk_dt_wo
        FOREIGN KEY(wo_number)
        REFERENCES work_order(wo_number)
);

-- ==========================================================
-- MAINTENANCE
-- ==========================================================

CREATE TABLE maintenance
(
    maintenance_no      VARCHAR(20) PRIMARY KEY,

    machine_code        VARCHAR(10) NOT NULL,

    maintenance_type    VARCHAR(20) NOT NULL,

    start_time          DATETIME NOT NULL,

    finish_time         DATETIME NOT NULL,

    duration_minutes    INT NOT NULL,

    technician          VARCHAR(20) NOT NULL,

    status              VARCHAR(20) NOT NULL,

    CONSTRAINT fk_mt_machine
        FOREIGN KEY(machine_code)
        REFERENCES machine(machine_code)
);

-- ==========================================================
-- INVENTORY TRANSACTION
-- ==========================================================

CREATE TABLE inventory_transaction
(
    transaction_no      VARCHAR(20) PRIMARY KEY,

    transaction_date    DATETIME NOT NULL,

    material_name       VARCHAR(100) NOT NULL,

    transaction_type    VARCHAR(20) NOT NULL,

    quantity            INT NOT NULL,

    stock_after         INT NOT NULL,

    supplier            VARCHAR(100)
);

-- ==========================================================
-- INDEX
-- ==========================================================

CREATE INDEX idx_workorder_product
ON work_order(product_code);

CREATE INDEX idx_workorder_machine
ON work_order(machine_code);

CREATE INDEX idx_workorder_employee
ON work_order(employee_no);

CREATE INDEX idx_workorder_status
ON work_order(status);

CREATE INDEX idx_workorder_planstart
ON work_order(plan_start);

CREATE INDEX idx_production_wo
ON production_result(wo_number);

CREATE INDEX idx_production_start
ON production_result(actual_start);

CREATE INDEX idx_downtime_wo
ON downtime(wo_number);

CREATE INDEX idx_downtime_reason
ON downtime(downtime_reason);

CREATE INDEX idx_maintenance_machine
ON maintenance(machine_code);

CREATE INDEX idx_inventory_material
ON inventory_transaction(material_name);

CREATE INDEX idx_inventory_date
ON inventory_transaction(transaction_date);

